class MagicBullet : public cocos2d::Sprite {
public:
    static MagicBullet* create(const cocos2d::Vec2& startPos, const cocos2d::Vec2& targetPos);

    void update(float dt) override;

private:
    cocos2d::Vec2 _velocity;
    float _speed = 600.0f; // Bullet speed in pixels per second
};

// MagicBullet.cpp
#include "MagicBullet.h"

MagicBullet* MagicBullet::create(const cocos2d::Vec2& startPos, const cocos2d::Vec2& targetPos) {
    MagicBullet* bullet = new (std::nothrow) MagicBullet();
    if (bullet && bullet->initWithFile("bullet.png")) {
        bullet->autorelease();
        bullet->setPosition(startPos);

        // Calculate normalized direction vector towards target
        cocos2d::Vec2 direction = targetPos - startPos;
        direction.normalize();

        // Set velocity vector
        bullet->_velocity = direction * bullet->_speed;

        // Schedule update to move bullet every frame
        bullet->scheduleUpdate();

        return bullet;
    }
    CC_SAFE_DELETE(bullet);
    return nullptr;
}

void MagicBullet::update(float dt) {
    // Move bullet along velocity vector
    cocos2d::Vec2 newPos = this->getPosition() + _velocity * dt;
    this->setPosition(newPos);

    // Optionally: check collision with target or boundaries here and remove bullet if needed
}

// Example of firing a magic bullet
void YourGameLayer::fireMagicBullet(const cocos2d::Vec2& startPos, const cocos2d::Vec2& enemyPos) {
    auto bullet = MagicBullet::create(startPos, enemyPos);
    this->addChild(bullet);
}

