float length(const Vec2& v) {
    return std::sqrt(v.x*v.x + v.y*v.y);
}

float distance(const Vec2& a, const Vec2& b) {
    return length(Vec2{b.x - a.x, b.y - a.y});
}

Vec2 normalize(const Vec2& v) {
    float len = length(v);
    if (len > 1e-6f) return Vec2{v.x / len, v.y / len};
    return Vec2{0.0f, 0.0f};
}

// Solve for intercept direction.
// Returns optional<Vec2> normalized direction where a projectile launched from 'shooterPos'
// with speed projectileSpeed will intercept a target currently at targetPos moving with targetVel.
// If no intercept is possible (projectile too slow), returns std::nullopt.
std::optional<Vec2> ComputeInterceptDirection(const Vec2& shooterPos,
                                              const Vec2& targetPos,
                                              const Vec2& targetVel,
                                              float projectileSpeed) {
    Vec2 toTarget{ targetPos.x - shooterPos.x, targetPos.y - shooterPos.y };

    // Quadratic coefficients for solving t: |targetPos + targetVel * t - shooterPos|^2 = (projectileSpeed*t)^2
    float vx = targetVel.x;
    float vy = targetVel.y;
    float dx = toTarget.x;
    float dy = toTarget.y;

    float a = vx*vx + vy*vy - projectileSpeed*projectileSpeed;
    float b = 2.0f * (dx*vx + dy*vy);
    float c = dx*dx + dy*dy;

    // Solve a*t^2 + b*t + c = 0
    float t = -1.0f;
    if (std::fabs(a) < 1e-6f) {
        // Degenerate -> linear equation b*t + c = 0
        if (std::fabs(b) < 1e-6f) return std::nullopt; // No solution
        float tt = -c / b;
        if (tt > 0) t = tt;
    } else {
        float disc = b*b - 4.0f*a*c;
        if (disc < 0) return std::nullopt; // no real solution -> can't intercept
        float sqrtD = std::sqrt(disc);
        float t1 = (-b + sqrtD) / (2.0f * a);
        float t2 = (-b - sqrtD) / (2.0f * a);

        // Want smallest positive t
        float cand = std::numeric_limits<float>::infinity();
        if (t1 > 1e-6f) cand = std::min(cand, t1);
        if (t2 > 1e-6f) cand = std::min(cand, t2);
        if (cand < std::numeric_limits<float>::infinity()) t = cand;
    }

    if (t <= 0.0f) return std::nullopt;

    // Intercept point
    Vec2 interceptPoint{ targetPos.x + targetVel.x * t, targetPos.y + targetVel.y * t };
    Vec2 dir{ interceptPoint.x - shooterPos.x, interceptPoint.y - shooterPos.y };
    return normalize(dir);
}

// Angle in degrees for printing
float angleDegrees(const Vec2& dir) {
    return std::atan2(dir.y, dir.x) * (180.0f / 3.14159265358979323846f);
}

Player* findClosestEnemy(Player* local, std::vector<Player>& players) {
    if (!local) return nullptr;
    Player* best = nullptr;
    float bestDist = std::numeric_limits<float>::infinity();
    for (auto& p : players) {
        if (&p == local) continue;
        if (p.isLocal) continue;
        float d = distance(local->position, p.position);
        if (d < bestDist) {
            bestDist = d;
            best = &p;
        }
    }
    return best;
}

